import mpmath

def fmt_match(x, spec, ref):
    try:
        got = format(x, spec)
    except Exception as exc:
        got = "EXC:%s" % type(exc).__name__
    return 1.0 if got == ref else 0.0

# example 1: format spec '.016f' (leading zero before precision) on mp.mpf('0.1')
probe("fmt_leading_zero_precision_016f_x0p1",
      fmt_match(mpmath.mpf("0.1"), ".016f", format(0.1, ".016f")))

# example 2: format spec '0030f' (zero-padded width with leading zero) on mp.mpf('0.3')
probe("fmt_leading_zero_width_0030f_x0p3",
      fmt_match(mpmath.mpf("0.3"), "0030f", format(0.3, "0030f")))

def exc_code(fn):
    try:
        fn()
        return 0.0
    except OverflowError:
        return 1.0
    except ValueError:
        return 2.0
    except Exception:
        return 3.0

# example 3: round/int of infinity must raise OverflowError as CPython does
probe("round_inf_exc_code_overflow1_value2_other3",
      exc_code(lambda: round(mpmath.mpf("inf"))))
probe("int_inf_exc_code_overflow1_value2_other3",
      exc_code(lambda: int(mpmath.mpf("inf"))))

